  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The ATLAS and CMS discovery established the Higgs boson and completed a central part of the Standard Model, with enduring significance for particle physics.",
        "attribution": "These leaders represent the two experiments that independently observed the signal. Credit is necessarily collective; their roles in building and leading the experiments support individual recognition.",
        "maturity": "The discovery has been confirmed through extensive measurements of Higgs properties and decay channels over many years.",
        "uncertainties": [
          "The scale and distributed nature of the collaborations make any small set of individual laureates an incomplete representation of the experimental work."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Francis Halzen",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "The detection of high-energy astrophysical neutrinos opened a new observational window on the Universe and established neutrino astronomy as a field.",
        "attribution": "Halzen's scientific leadership and Spiering's long work developing and organizing the detector effort represent central theoretical and experimental contributions; the result also depended on a large collaboration.",
        "maturity": "The astrophysical signal has been supported by years of data and follow-up analyses, though source identification remains an active area.",
        "uncertainties": [
          "The individual credit balance between detector conception, construction, analysis, and later source studies is difficult to capture in two names."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Heino Falcke",
        "J. Anton Zensus",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Imaging the shadow of a black hole was a remarkable technical and scientific achievement that tested strong-gravity predictions and made horizon-scale astronomy possible.",
        "attribution": "Falcke articulated the shadow-imaging concept, while Zensus and Doeleman were central to the global VLBI effort and its implementation. The result rests on a broad international collaboration.",
        "maturity": "The M87 and Sgr A* results, with continued imaging and analysis, make this a durable observational accomplishment.",
        "uncertainties": [
          "The image depends on complex reconstruction methods and calibration choices, although independent analyses and later observations strengthen confidence."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B061",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of the cosmic microwave background made precision cosmology possible and sharply constrained the Universe's age, composition, and evolution.",
        "attribution": "Bennett led the mission and instrument work, while Spergel and Page made major contributions to cosmological interpretation and experimental leadership. The team was large, so individual selection is necessarily selective.",
        "maturity": "Its central results have been tested and refined by later CMB measurements and are now foundational to standard cosmology.",
        "uncertainties": [
          "The distinction between WMAP's contribution and the broader sequence of CMB experiments complicates attribution."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "Matthew Colless",
        "Shaun Cole"
      ],
      "assessment": {
        "nobel_worthiness": "Establishing baryon acoustic oscillations as a standard ruler gave cosmology a powerful method for measuring cosmic expansion and dark energy.",
        "attribution": "Eisenstein, Colless, and Cole were central to the early theoretical and observational demonstration through large galaxy surveys. Credit is distributed across the survey teams and subsequent measurements.",
        "maturity": "The standard-ruler method has been repeatedly measured across surveys and remains a major tool in observational cosmology.",
        "uncertainties": [
          "The contribution may be judged as a gradual development across several teams rather than a single sharply bounded discovery."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault-tolerant codes showed how quantum computation can overcome noise in principle, shaping a major field across physics and information science.",
        "attribution": "Shor and Steane independently established foundational error-correcting codes, while Kitaev developed influential topological approaches. The listed names cover distinct, consequential strands.",
        "maturity": "The theory is well established and experimental demonstrations of error correction and logical operations have advanced substantially.",
        "uncertainties": [
          "The connection between these foundational results and scalable, practically useful fault-tolerant quantum computers remains incomplete."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Enrico Costa",
        "Filippo Frontera",
        "Shrinivas R. Kulkarni"
      ],
      "assessment": {
        "nobel_worthiness": "Identifying afterglows and establishing the cosmological distances of gamma-ray bursts transformed them from enigmatic flashes into powerful probes of extreme astrophysics.",
        "attribution": "Costa and Frontera were central to the BeppoSAX observations that enabled rapid localization and afterglow discovery; Kulkarni led pivotal follow-up observations that established the distances.",
        "maturity": "The cosmological origin and broad physical picture are secure, with decades of observations expanding the subject.",
        "uncertainties": [
          "The discovery unfolded through coordinated observations by multiple teams, making the boundary of decisive credit contestable."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision metrology, enabling unprecedented frequency standards and tests of fundamental physics.",
        "attribution": "Katori and Ye independently developed leading approaches and experiments, giving a clear basis for shared recognition.",
        "maturity": "The technology has reached extraordinary precision and has been replicated and extended by many groups.",
        "uncertainties": [
          "The Nobel case depends on weighing a major measurement advance against the possibility that its broadest scientific consequences are still emerging."
        ]
      }
    }
  ]
}
